/* Pure PCM processing shared by preview and export. */
function cutPCM(buffer,start,end,gain=1,fade=false){const rate=buffer.sampleRate,a=Math.round(start*rate),b=Math.min(buffer.length,Math.round(end*rate)),n=b-a;if(n<1)throw Error('请选择至少一个采样点。');const ramp=Math.min(Math.round(rate*.15),Math.floor(n/2));return Array.from({length:buffer.numberOfChannels},(_,ch)=>{const src=buffer.getChannelData(ch),dst=new Float32Array(n);for(let i=0;i<n;i++){const envelope=fade&&ramp>0?Math.min(1,i/ramp,(n-1-i)/ramp):1;dst[i]=Math.max(-1,Math.min(1,src[a+i]*gain*envelope));}return dst;});}
function encodeWav(channels,rate){const count=channels.length,n=channels[0].length,view=new DataView(new ArrayBuffer(44+n*count*2));function str(p,s){for(let i=0;i<s.length;i++)view.setUint8(p+i,s.charCodeAt(i));}str(0,'RIFF');view.setUint32(4,36+n*count*2,true);str(8,'WAVE');str(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,count,true);view.setUint32(24,rate,true);view.setUint32(28,rate*count*2,true);view.setUint16(32,count*2,true);view.setUint16(34,16,true);str(36,'data');view.setUint32(40,n*count*2,true);for(let i=0,p=44;i<n;i++)for(let c=0;c<count;c++,p+=2){const s=channels[c][i];view.setInt16(p,Math.round(s*(s<0?32768:32767)),true);}return view.buffer;}
if(typeof module!=='undefined')module.exports={cutPCM,encodeWav};
